        $category_id=(int)($this->request->get['probg_service_category_id']??0);$service_id=(int)($this->request->get['probg_service_id']??0);$route=(string)($this->request->get['route']??'');$is_request=$route==='extension/module/probg_services'||$category_id||$service_id;
        if(!$is_request||self::$full_page_rendering)return $this->module($setting);self::$full_page_rendering=true;$output=$service_id?$this->service($service_id,$category_id):($category_id?$this->category($category_id):$this->listing());self::$full_page_rendering=false;return $output;
