    private function relatedProducts($service_id){$products=array();$this->load->model('catalog/product');$theme=$this->config->get('config_theme');$w=(int)$this->config->get('theme_'.$theme.'_image_product_width')?:200;$h=(int)$this->config->get('theme_'.$theme.'_image_product_height')?:200;foreach($this->model_extension_probg_services_service->getServiceProducts($service_id) as $product_id){$r=$this->model_catalog_product->getProduct($product_id);if(!$r)continue;$price=($this->customer->isLogged()||!$this->config->get('config_customer_price'))?$this->currency->format($this->tax->calculate($r['price'],$r['tax_class_id'],$this->config->get('config_tax')),$this->session->data['currency']):false;$special=!is_null($r['special'])&&$r['special']>=0?$this->currency->format($this->tax->calculate($r['special'],$r['tax_class_id'],$this->config->get('config_tax')),$this->session->data['currency']):false;$products[]=array('product_id'=>$r['product_id'],'thumb'=>$r['image']?$this->model_tool_image->resize($r['image'],$w,$h):'','name'=>$r['name'],'description'=>utf8_substr(trim(strip_tags(html_entity_decode($r['description'],ENT_QUOTES,'UTF-8'))),0,100).'..','price'=>$price,'special'=>$special,'rating'=>$this->config->get('config_review_status')?(int)$r['rating']:false,'href'=>$this->url->link('product/product','product_id='.$r['product_id'],true));}return $products;}
