    private function social($title,$description,$url,$schema_type,$image='',$service=array(),$breadcrumbs=array()){$site=$this->config->get('config_name');$meta='<meta property="og:type" content="website" />\n<meta property="og:title" content="'.htmlspecialchars($title,ENT_QUOTES,'UTF-8').'" />\n<meta property="og:description" content="'.htmlspecialchars(strip_tags($description),ENT_QUOTES,'UTF-8').'" />\n<meta property="og:url" content="'.htmlspecialchars($url,ENT_QUOTES,'UTF-8').'" />\n<meta property="og:site_name" content="'.htmlspecialchars($site,ENT_QUOTES,'UTF-8').'" />\n';if($image)$meta.='<meta property="og:image" content="'.htmlspecialchars($image,ENT_QUOTES,'UTF-8').'" />\n';$meta.='<meta name="twitter:card" content="'.($image?'summary_large_image':'summary').'" />\n<meta name="twitter:title" content="'.htmlspecialchars($title,ENT_QUOTES,'UTF-8').'" />\n<meta name="twitter:description" content="'.htmlspecialchars(strip_tags($description),ENT_QUOTES,'UTF-8').'" />\n';if($image)$meta.='<meta name="twitter:image" content="'.htmlspecialchars($image,ENT_QUOTES,'UTF-8').'" />\n';$json=array('@context'=>'https://schema.org','@type'=>$schema_type,'name'=>$title,'url'=>$url);if($description)$json['description']=strip_tags($description);if($image)$json['image']=$image;if($schema_type==='Service'){$json['provider']=$this->provider();if(!empty($service['show_price']))$json['offers']=array('@type'=>'Offer','price'=>(string)$service['price'],'priceCurrency'=>$this->session->data['currency'],'url'=>$url);}$meta.='<script type="application/ld+json">'.json_encode($json,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).'</script>';if($breadcrumbs){$items=array();$pos=1;foreach($breadcrumbs as $b)$items[]=array('@type'=>'ListItem','position'=>$pos++,'name'=>$b['text'],'item'=>$b['href']);$meta.='<script type="application/ld+json">'.json_encode(array('@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>$items),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICOD